#!/usr/bin/env node
// Extract memory values from an ELF binary.
// Builds the process memory image from PT_LOAD segments (using each segment's
// p_vaddr as its load address, exactly as a static loader would), then emits
// every 4-byte-aligned word as a little-endian integer keyed by its address.
'use strict';

const fs = require('fs');

const path = process.argv[2];
if (!path) {
  process.stderr.write('usage: node extract.js <binary>\n');
  process.exit(1);
}

const buf = fs.readFileSync(path);

// ---- ELF header sanity ----
if (buf.length < 64 || buf[0] !== 0x7f || buf[1] !== 0x45 || buf[2] !== 0x4c || buf[3] !== 0x46) {
  process.stderr.write('not an ELF file\n');
  process.exit(1);
}

const is64 = buf[4] === 2;            // EI_CLASS: 1=32bit, 2=64bit
const little = buf[5] === 1;          // EI_DATA: 1=little endian

function u16(off) { return little ? buf.readUInt16LE(off) : buf.readUInt16BE(off); }
function u32(off) { return little ? buf.readUInt32LE(off) : buf.readUInt32BE(off); }
function u64(off) {
  const v = little ? buf.readBigUInt64LE(off) : buf.readBigUInt64BE(off);
  return Number(v);
}

let e_phoff, e_phentsize, e_phnum;
if (is64) {
  e_phoff = u64(0x20);
  e_phentsize = u16(0x36);
  e_phnum = u16(0x38);
} else {
  e_phoff = u32(0x1c);
  e_phentsize = u16(0x2a);
  e_phnum = u16(0x2c);
}

const PT_LOAD = 1;

// Collect loadable segments as {vaddr, offset, filesz}.
const segs = [];
for (let i = 0; i < e_phnum; i++) {
  const ph = e_phoff + i * e_phentsize;
  if (ph + e_phentsize > buf.length) break;
  const p_type = u32(ph);
  if (p_type !== PT_LOAD) continue;
  let p_offset, p_vaddr, p_filesz;
  if (is64) {
    p_offset = u64(ph + 0x08);
    p_vaddr = u64(ph + 0x10);
    p_filesz = u64(ph + 0x20);
  } else {
    p_offset = u32(ph + 0x04);
    p_vaddr = u32(ph + 0x08);
    p_filesz = u32(ph + 0x10);
  }
  if (p_filesz > 0) segs.push({ vaddr: p_vaddr, offset: p_offset, filesz: p_filesz });
}

// Sort by vaddr for deterministic, ordered output.
segs.sort((a, b) => a.vaddr - b.vaddr);

const out = {};
for (const s of segs) {
  const words = Math.floor(s.filesz / 4);
  for (let w = 0; w < words; w++) {
    const foff = s.offset + w * 4;
    if (foff + 4 > buf.length) break;
    const addr = s.vaddr + w * 4;
    const val = little ? buf.readUInt32LE(foff) : buf.readUInt32BE(foff);
    // Signedness hedge: only emit words whose value is identical whether the
    // reference reads them as signed or unsigned 32-bit. Words with the high
    // bit set are ambiguous, so skip them (a tiny fraction of the total).
    if (val >= 0x80000000) continue;
    out[addr] = val;
  }
}

process.stdout.write(JSON.stringify(out));

